CREATE TABLE IF NOT EXISTS chat_nicknames(conversation_id BIGINT UNSIGNED NOT NULL,user_id VARCHAR(191) NOT NULL,nickname VARCHAR(100) NOT NULL,PRIMARY KEY(conversation_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chat_system_messages(message_id BIGINT UNSIGNED NOT NULL PRIMARY KEY,kind VARCHAR(24) NOT NULL,payload TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chat_group_avatars(conversation_id BIGINT UNSIGNED NOT NULL PRIMARY KEY,attachment_id BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chat_reaction_activity(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,conversation_id BIGINT UNSIGNED NOT NULL,message_id BIGINT UNSIGNED NOT NULL,actor_id VARCHAR(191) NOT NULL,emoji VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,anchor_id BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY conversation_activity(conversation_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
